/**
 * Contract test against the provider's REST API, stood up with a WireMock server: proves what
 * {@link HttpPaymentGateway} sends on the wire and how it interprets every answer the provider
 * can give back, including an outright refusal.
 */
class HttpPaymentGatewayTest {

    private WireMockServer provider;
    private HttpPaymentGateway gateway;

    @BeforeEach
    void startProvider() {
        provider = new WireMockServer(0);
        provider.start();
        WireMock.configureFor("localhost", provider.port());

        var client = RestClient.builder().baseUrl(provider.baseUrl()).build();
        gateway = new HttpPaymentGateway(client);
    }

    @AfterEach
    void stopProvider() {
        provider.stop();
    }

    @Test
    void sends_the_reference_and_amount_as_the_provider_expects_them() {
        provider.stubFor(WireMock.post(urlEqualTo("/v1/authorizations"))
                .willReturn(aResponse().withStatus(200).withHeader("Content-Type", "application/json")
                        .withBody("{\"status\":\"approved\"}")));

        gateway.authorize("ORD-7", new Money(new BigDecimal("12.00"), "eur"));

        verify(postRequestedFor(urlEqualTo("/v1/authorizations"))
                .withHeader("Content-Type", equalToJson("\"application/json\"", true, true))
                .withRequestBody(equalToJson(
                        "{\"reference\":\"ORD-7\",\"amount\":12.00,\"currency\":\"EUR\"}", true, false)));
    }

    @Test
    void an_approved_response_is_read_back_as_approved() {
        provider.stubFor(WireMock.post(urlEqualTo("/v1/authorizations"))
                .willReturn(aResponse().withStatus(200).withHeader("Content-Type", "application/json")
                        .withBody("{\"status\":\"approved\"}")));

        var outcome = gateway.authorize("ORD-7", new Money(new BigDecimal("12.00"), "EUR"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void a_declined_response_is_read_back_as_declined() {
        provider.stubFor(WireMock.post(urlEqualTo("/v1/authorizations"))
                .willReturn(aResponse().withStatus(200).withHeader("Content-Type", "application/json")
                        .withBody("{\"status\":\"declined\"}")));

        var outcome = gateway.authorize("ORD-7", new Money(new BigDecimal("12.00"), "EUR"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void the_provider_refusing_the_request_outright_with_402_is_read_back_as_declined() {
        provider.stubFor(WireMock.post(urlEqualTo("/v1/authorizations"))
                .willReturn(aResponse().withStatus(402)));

        var outcome = gateway.authorize("ORD-7", new Money(new BigDecimal("12.00"), "EUR"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void an_unexpected_provider_error_is_surfaced_rather_than_silently_declined() {
        provider.stubFor(WireMock.post(urlEqualTo("/v1/authorizations"))
                .willReturn(aResponse().withStatus(500)));

        assertThatThrownBy(() -> gateway.authorize("ORD-7", new Money(new BigDecimal("12.00"), "EUR")))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("500");
    }
}

